import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.CZqXuAiL.js";const g=JSON.parse(`{"title":"Console Command","description":"The p:trashbin:purge artisan command — how Trash Bin Pro's hourly retention purge works, how it is scheduled, and when to run it manually.","frontmatter":{"title":"Console Command","description":"The p:trashbin:purge artisan command — how Trash Bin Pro's hourly retention purge works, how it is scheduled, and when to run it manually."},"headers":[],"relativePath":"trash-bin-pro/user-guide/cli.md","filePath":"trash-bin-pro/user-guide/cli.md","lastUpdated":1785512893000}`),n={name:"trash-bin-pro/user-guide/cli.md"};function r(o,e,l,h,d,p){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="console-command" tabindex="-1">Console Command <a class="header-anchor" href="#console-command" aria-label="Permalink to &quot;Console Command&quot;">​</a></h1><p>Trash Bin Pro ships exactly one artisan command: the retention purge that permanently deletes trashed files whose retention window has expired.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> p:trashbin:purge</span></span></code></pre></div><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Signature</td><td><code>p:trashbin:purge</code></td></tr><tr><td>Class</td><td><code>Pterodactyl\\Console\\Commands\\TrashBinPro\\PurgeTrashCommand</code></td></tr><tr><td>Options</td><td>None</td></tr><tr><td>Exit code</td><td>Always <code>0</code> (success) — see <a href="#exit-behavior">Exit behavior</a></td></tr></tbody></table><hr><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><p>Each run walks the <code>trashbin_files</code> table and deletes everything past its retention window:</p><ol><li><strong>Bail out early if not migrated.</strong> If the <code>trashbin_files</code> table does not exist yet, the command prints <code>Trash Bin Pro tables are not migrated yet — nothing to purge.</code> and exits successfully.</li><li><strong>Chunk the table.</strong> Rows are read with <code>chunkById</code> in batches of <code>purge_batch_size</code> (global setting, default <code>200</code>, floored at <code>50</code>), so large trash backlogs never load into memory at once.</li><li><strong>Evaluate retention per row.</strong> Each row is checked against the <em>effective</em> retention for its server — server override, then egg override, then the global <code>retention_hours</code>. A row is expired when <code>created_at + retention</code> is in the past. The timestamp math is non-mutating (<code>CarbonImmutable</code>), so evaluation never touches the stored <code>created_at</code>.</li><li><strong>Drop orphans.</strong> Rows whose server no longer exists (deleted server) have no files on any node — their DB records are deleted directly, no Wings call.</li><li><strong>One Wings call per server.</strong> Expired IDs are grouped per server and deleted with a single <code>deleteFiles(&#39;/.trash&#39;, [ids...])</code> call to that server&#39;s node. The DB rows are removed only after Wings confirms the delete.</li></ol><h3 id="example-output" tabindex="-1">Example output <a class="header-anchor" href="#example-output" aria-label="Permalink to &quot;Example output&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ php artisan p:trashbin:purge</span></span>
<span class="line"><span>Purged 12 expired file(s).</span></span></code></pre></div><p>When one or more nodes could not be reached, the command adds a warning line but still succeeds:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ php artisan p:trashbin:purge</span></span>
<span class="line"><span>Purged 4 expired file(s).</span></span>
<span class="line"><span>2 server(s) could not be reached and will be retried next run.</span></span></code></pre></div><h3 id="exit-behavior" tabindex="-1">Exit behavior <a class="header-anchor" href="#exit-behavior" aria-label="Permalink to &quot;Exit behavior&quot;">​</a></h3><p>The command <strong>always returns exit code 0</strong>, even when some servers fail. A per-server failure (node offline, Wings timeout, server suspended) is caught, logged, and skipped — the failed rows are left in the database and retried automatically on the next hourly run. One dead node never blocks purging for every other server.</p><p>Failures land in <code>storage/logs/laravel.log</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[TrashBinPro] Failed to purge trash for server 17: &lt;wings error message&gt;</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Monitoring</p><p>Do not alert on the exit code — alert on the log line above, or on the <code>N server(s) could not be reached</code> warning. A node that is down for days will keep its trash until it comes back, which is the intended behavior.</p></div><hr><h2 id="scheduling" tabindex="-1">Scheduling <a class="header-anchor" href="#scheduling" aria-label="Permalink to &quot;Scheduling&quot;">​</a></h2><p>You do <strong>not</strong> add a cron entry for this command. <code>TrashBinProServiceProvider</code> registers it with Laravel&#39;s scheduler at boot:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$schedule</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">command</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;p:trashbin:purge&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hourly</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">withoutOverlapping</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><ul><li><strong>Hourly</strong> — runs at the top of every hour.</li><li><strong><code>withoutOverlapping()</code></strong> — a slow run (many servers, large backlog) can never stack on top of itself.</li><li>Registered by the service provider, <strong>not</strong> by editing <code>app/Console/Kernel.php</code> — so panel updates cannot clobber it.</li></ul><div class="warning custom-block"><p class="custom-block-title">The panel&#39;s scheduler cron must exist</p><p>This only works if Pterodactyl&#39;s standard scheduler cron is installed — the same one every panel already needs:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cd /var/www/pterodactyl &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schedule:run</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/null</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span></span></code></pre></div><p>If <code>schedule:run</code> never fires, nothing is ever purged and trash grows until it hits the per-server cap.</p></div><p>Verify the command is registered:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> p:trashbin</span></span></code></pre></div><hr><h2 id="running-it-manually" tabindex="-1">Running it manually <a class="header-anchor" href="#running-it-manually" aria-label="Permalink to &quot;Running it manually&quot;">​</a></h2><p>The hourly schedule covers normal operation. Run it by hand when:</p><ul><li><strong>You lowered retention</strong> (globally, per egg, or per server) and want the shorter window applied to existing trash now instead of waiting for the next hour.</li><li><strong>Before a big cleanup or migration</strong> — e.g. freeing disk on a node before maintenance.</li><li><strong>Testing the install</strong> — trash a file on a test server, set retention to <code>1</code> hour, backdate nothing, and confirm the flow end to end. For an immediate check, use <strong>Admin → Trash Bin Pro → Purge now</strong>, which runs the same purge on demand.</li></ul><p>From the admin panel there is also a <strong>Purge now</strong> button (<code>POST /admin/trashbinpro/purge-now</code>) that triggers the same purge without SSH access.</p><hr><h2 id="installing-blueprint" tabindex="-1">Installing (Blueprint) <a class="header-anchor" href="#installing-blueprint" aria-label="Permalink to &quot;Installing (Blueprint)&quot;">​</a></h2><p>For completeness — the extension itself is installed with Blueprint:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactyltrashbinpro-v1.0.2.blueprint</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span></code></pre></div><p>The standalone installer (<code>standalone/data/install.sh</code>) registers the same command and schedule. See <a href="./../getting-started/installation">Installation</a>.</p>`,35)])])}const u=s(n,[["render",r]]);export{g as __pageData,u as default};
